
import re
import math
from xml.etree import ElementTree as ET

def apply_matrix(matrix, x, y):
    a, b, c, d, e, f = matrix
    return (a * x + c * y + e, b * x + d * y + f)

def parse_matrix(transform_str):
    m = re.search(r'matrix\(([^)]+)\)', transform_str)
    if m:
        return list(map(float, m.group(1).split(',')))
    return [1, 0, 0, 1, 0, 0]

def parse_translate(transform_str):
    m = re.search(r'translate\(([^)]+)\)', transform_str)
    if m:
        parts = list(map(float, m.group(1).split(',')))
        tx = parts[0]
        ty = parts[1] if len(parts) > 1 else 0
        return [1, 0, 0, 1, tx, ty]
    return [1, 0, 0, 1, 0, 0]

def combine_matrices(a, b):
    a1, a2, a3, a4, a5, a6 = a
    b1, b2, b3, b4, b5, b6 = b
    return [
        a1*b1 + a3*b2,
        a2*b1 + a4*b2,
        a1*b3 + a3*b4,
        a2*b3 + a4*b4,
        a1*b5 + a3*b6 + a5,
        a2*b5 + a4*b6 + a6
    ]

def parse_path(d):
    tokens = re.findall(r'[a-zA-Z]|-?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?', d)
    i = 0
    curr = [0.0, 0.0]
    start = [0.0, 0.0]
    cmd = None
    segments = []
    while i < len(tokens):
        t = tokens[i]
        if re.fullmatch(r'[a-zA-Z]', t):
            cmd = t
            i += 1
        lower = cmd.lower()
        if lower == 'm':
            x = float(tokens[i]); y = float(tokens[i+1]); i += 2
            if cmd == 'm':
                curr[0] += x; curr[1] += y
            else:
                curr[0] = x; curr[1] = y
            start[:] = curr
            segments.append(('M', list(curr)))
            cmd = 'l' if cmd == 'm' else 'L'
        elif lower == 'l':
            x = float(tokens[i]); y = float(tokens[i+1]); i += 2
            if cmd == 'l':
                curr[0] += x; curr[1] += y
            else:
                curr[0] = x; curr[1] = y
            segments.append(('L', list(curr)))
        elif lower == 'c':
            pts = [float(tokens[i+j]) for j in range(6)]
            i += 6
            if cmd == 'c':
                x1, y1, x2, y2, x, y = pts
                ax1, ay1 = curr[0]+x1, curr[1]+y1
                ax2, ay2 = curr[0]+x2, curr[1]+y2
                ax, ay = curr[0]+x, curr[1]+y
            else:
                ax1, ay1, ax2, ay2, ax, ay = pts
            segments.append(('C', [ax1, ay1, ax2, ay2, ax, ay]))
            curr[:] = [ax, ay]
        elif lower == 'z':
            curr[:] = start
            segments.append(('Z', []))
        else:
            raise ValueError(f'Unsupported command: {cmd}')
    return segments

def transform_segments(segments, matrix):
    transformed = []
    for seg in segments:
        t, pts = seg
        tpts = [apply_matrix(matrix, p[0], p[1]) for p in [pts[i:i+2] for i in range(0, len(pts), 2)]]
        transformed.append((t, [coord for p in tpts for coord in p]))
    return transformed

def fmt(v):
    s = f"{v:.1f}"
    return s[:-2] if s.endswith('.0') else s

